function example(kind){const c=document.createElement('canvas');c.width=1100;c.height=760;const x=c.getContext('2d');x.fillStyle='#666b60';x.fillRect(0,0,1100,760);if(kind==='blank'){let g=x.createRadialGradient(400,280,20,520,400,700);g.addColorStop(0,'#a6b09b');g.addColorStop(.5,'#72826b');g.addColorStop(1,'#26382e');x.fillStyle=g;x.fillRect(0,0,1100,760);return c;}
 const vp=[560,335],rect=[450,235,670,435];function poly(p,fill){x.beginPath();p.forEach(([a,b],i)=>i?x.lineTo(a,b):x.moveTo(a,b));x.closePath();x.fillStyle=fill;x.fill();}poly([[0,0],[1100,0],[670,235],[450,235]],'#969a8b');poly([[0,0],[450,235],[450,435],[0,760]],'#747e71');poly([[1100,0],[670,235],[670,435],[1100,760]],'#59665b');poly([[0,760],[450,435],[670,435],[1100,760]],'#858477');poly([[450,235],[670,235],[670,435],[450,435]],'#c0c5ae');
 let seed=9;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}function line(a,b,width=3,color='#333e35',alter=true){if(kind==='broken'&&alter){let mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2,theta=(rand()-.5)*.45,cs=Math.cos(theta),sn=Math.sin(theta);a=[mx+(a[0]-mx)*cs-(a[1]-my)*sn,my+(a[0]-mx)*sn+(a[1]-my)*cs];b=[mx+(b[0]-mx)*cs-(b[1]-my)*sn,my+(b[0]-mx)*sn+(b[1]-my)*cs];}x.beginPath();x.moveTo(...a);x.lineTo(...b);x.strokeStyle=color;x.lineWidth=width;x.stroke();}
 for(let j=0;j<4;j++)line([[0,0],[1100,0],[1100,760],[0,760]][j],[[450,235],[670,235],[670,435],[450,435]][j],4);
 for(const t of [.08,.29,.47,.62,.74,.83]){let l=vp[0]*(1-t),r=vp[0]+(1100-vp[0])*t; // frames at increasing depth, projected from the same center
 let left=560*(1-t),right=560+540*t,top=335*(1-t),bottom=335+425*t;
 if(t<.22)continue;line([left,top],[left,bottom],5);line([right,top],[right,bottom],5);line([left,top],[right,top],4);line([left,bottom],[right,bottom],3);
 }
 for(let b=60;b<1100;b+=130){let t=(435-335)/(760-335);line([b,760],[560+(b-560)*t,435],2,'#424b40');}
 for(const yy of [80,155,610,680]){let t=450/560;line([0,yy],[450,yy+(335-yy)*t],3,'#aab19c');line([1100,yy],[670,yy+(335-yy)*(430/540)],3,'#919f8c');}
 // light fixture and far doorway
 poly([[510,265],[610,265],[610,435],[510,435]],'#273f35');poly([[522,276],[598,276],[598,435],[522,435]],'#688471');line([510,265],[610,265],3,'#d9debf',false);line([510,265],[510,435],3,'#c7cfb5',false);line([610,265],[610,435],3,'#c7cfb5',false);
 let glow=x.createRadialGradient(555,300,5,555,300,520);glow.addColorStop(0,'#e4edb715');glow.addColorStop(1,'#0b201c45');x.fillStyle=glow;x.fillRect(0,0,1100,760);return c;}
function load(image,name){source=image;lines=[];result=null;selected=-1;$('filename').textContent=name;$('dimensions').textContent=`${image.naturalWidth||image.width} × ${image.naturalHeight||image.height} px`;analyze();}
function analyze(reuse=false){if(!source)return;busy=true;$('canvasbadge').textContent='ANALYZING GEOMETRY';$('verdictLabel').textContent='Analyzing…';$('export').disabled=true;const c=document.createElement('canvas'),w=source.naturalWidth||source.width,h=source.naturalHeight||source.height,s=Math.min(1,720/Math.max(w,h));c.width=Math.round(w*s);c.height=Math.round(h*s);c.getContext('2d').drawImage(source,0,0,c.width,c.height);window.analysisSize=[c.width,c.height];worker.postMessage({id:++job,pixels:reuse?null:c.getContext('2d').getImageData(0,0,c.width,c.height).data,w:c.width,h:c.height,lines:reuse?lines:null,tolerance:+$('tolerance').value});draw();}
worker.onmessage=({data:d})=>{if(d.id!==job)return;busy=false;$('export').disabled=false;if(d.error){$('verdictLabel').textContent='Analysis unavailable';$('interpretation').textContent=d.error;$('canvasbadge').textContent='PLEASE TRY ANOTHER IMAGE';return;}lines=d.lines;result=d.result;report();draw();};worker.onerror=()=>{$('verdictLabel').textContent='Analysis unavailable';$('interpretation').textContent='Reload the app and try again.';busy=false;};
function report(){let strong=lines.length>=10&&result.groups.length>0,percent=Math.round(result.support*100),label=!strong?'Insufficient evidence':percent>=85?'Strong convergence':percent>=65?'Mixed convergence':'Weak convergence',color=!strong?'#aab4ad':percent>=85?colors[0]:percent>=65?colors[2]:'#fa807a';$('verdictLabel').textContent=label;$('verdictLabel').style.color=color;$('score').innerHTML=strong?`${percent}<small>%</small>`:'—';$('meterfill').style.width=(strong?percent:0)+'%';$('meterfill').style.background=color;$('statusdot').style.color=color;$('interpretation').textContent=!strong?'Too few reliable edges to assess perspective. Try an image with clear architectural lines.':percent>=85?'Most detected edges share a small set of vanishing directions. Inspect the overlay to verify the grouping.':'Some edges do not share the dominant directions. Inspect the red segments for possible mismatches.';$('edges').textContent=lines.length;$('families').textContent=result.groups.length;$('error').textContent=result.median===null?'—':result.median.toFixed(2)+'°';$('canvasbadge').textContent=label.toUpperCase();$('vpList').replaceChildren();result.groups.forEach((g,k)=>{let b=document.createElement('button');b.className='vp';b.style.width='100%';b.style.border='0';let v=g.v,[w,h]=window.analysisSize,inf=Math.abs(v[2])<1e-7,px=v[0]/v[2],py=v[1]/v[2],off=px<0||px>w||py<0||py>h; b.innerHTML=`<i style="background:${colors[k]}"></i> VP ${k+1}<small>${g.ids.length} edges · ${inf?'at infinity':off?'off canvas':'in frame'}</small>`;b.title='Click to isolate this direction family';b.onclick=()=>{selected=selected===k?-1:k;draw();};$('vpList').append(b);});if(!result.groups.length)$('vpList').textContent='No reliable families found';}
function draw(){if(!source)return;const box=$('stage').getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.height*dpr);ctx.scale(dpr,dpr);const iw=source.naturalWidth||source.width,ih=source.naturalHeight||source.height,scale=Math.min((box.width-48)/iw,(box.height-60)/ih),dw=iw*scale,dh=ih*scale,ox=(box.width-dw)/2,oy=(box.height-dh)/2;ctx.drawImage(source,ox,oy,dw,dh);if(original||!result)return;let [aw,ah]=window.analysisSize,s=dw/aw;ctx.save();ctx.translate(ox,oy);ctx.beginPath();ctx.rect(0,0,dw,dh);ctx.clip();
 if($('showRays').checked){ctx.lineWidth=.8;ctx.setLineDash([5,6]);result.groups.forEach((g,k)=>{if(selected>=0&&k!==selected)return;ctx.strokeStyle=colors[k]+'70';for(const i of g.ids){let l=lines[i],mx=(l.x1+l.x2)/2,my=(l.y1+l.y2)/2,v=g.v,px,py;if(Math.abs(v[2])<1e-7){px=mx+v[0]*10000;py=my+v[1]*10000;}else{px=v[0]/v[2];py=v[1]/v[2];}ctx.beginPath();ctx.moveTo(mx*s,my*s);ctx.lineTo(px*s,py*s);ctx.stroke();}});ctx.setLineDash([]);}
 if($('showLines').checked){ctx.lineWidth=2;lines.forEach((l,i)=>{let a=result.assignments[i];if(a.group<0&&!$('showOutliers').checked)return;if(selected>=0&&a.group!==selected)return;ctx.strokeStyle=a.group<0?'#fa807a':colors[a.group];ctx.beginPath();ctx.moveTo(l.x1*s,l.y1*s);ctx.lineTo(l.x2*s,l.y2*s);ctx.stroke();});}ctx.restore();
 result.groups.forEach((g,k)=>{if(selected>=0&&selected!==k)return;let v=g.v,inf=Math.abs(v[2])<1e-7,px=inf?aw/2+v[0]*100000:v[0]/v[2],py=inf?ah/2+v[1]*100000:v[1]/v[2];let off=px<0||px>aw||py<0||py>ah;let x=px*s,y=py*s;if(off){let dx=x-dw/2,dy=y-dh/2,t=Math.min((dw/2-20)/Math.max(Math.abs(dx),1),(dh/2-20)/Math.max(Math.abs(dy),1));x=dw/2+dx*t;y=dh/2+dy*t;}x+=ox;y+=oy;ctx.strokeStyle=colors[k];ctx.fillStyle='#111a14';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,9,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(x-13,y);ctx.lineTo(x+13,y);ctx.moveTo(x,y-13);ctx.lineTo(x,y+13);ctx.stroke();let text=`VP ${k+1}${inf?' ∞':off?' ↗':''}`,tx=Math.max(ox+5,Math.min(ox+dw-68,x+16)),ty=Math.max(oy+20,Math.min(oy+dh-6,y-14));ctx.font='11px monospace';ctx.fillStyle='#111a14e8';ctx.fillRect(tx-4,ty-13,65,20);ctx.fillStyle=colors[k];ctx.fillText(text,tx,ty);});}
async function openFile(file){if(!file)return;if(file.size>40*1024*1024){alert('Please choose an image smaller than 40 MB.');return;}let url=URL.createObjectURL(file),im=new Image();im.onload=()=>{load(im,file.name);document.querySelectorAll('.example').forEach(b=>b.classList.remove('selected'));URL.revokeObjectURL(url);};im.onerror=()=>{URL.revokeObjectURL(url);alert('This image could not be decoded. Try PNG, JPG or WebP.');};im.src=url;}
$('upload').onclick=()=>$('file').click();$('file').onchange=e=>{openFile(e.target.files[0]);e.target.value='';};let depth=0;document.addEventListener('dragenter',e=>{e.preventDefault();depth++;document.body.classList.add('drag');});document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('dragleave',()=>{if(--depth<=0)document.body.classList.remove('drag');});document.addEventListener('drop',e=>{e.preventDefault();depth=0;document.body.classList.remove('drag');openFile(e.dataTransfer.files[0]);});document.addEventListener('paste',e=>{let f=[...e.clipboardData.items].find(i=>i.type.startsWith('image/'));if(f)openFile(f.getAsFile());});
$('originalView').onclick=()=>{original=true;$('originalView').classList.add('active');$('analysisView').classList.remove('active');draw();};$('analysisView').onclick=()=>{original=false;$('analysisView').classList.add('active');$('originalView').classList.remove('active');draw();};for(const id of ['showLines','showRays','showOutliers'])$(id).onchange=draw;let timer;$('tolerance').oninput=()=>{$('toleranceValue').textContent=(+$('tolerance').value).toFixed(1)+'°';clearTimeout(timer);timer=setTimeout(()=>analyze(true),180);};$('about').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('export').onclick=()=>{if(busy)return;canvas.toBlob(b=>{if(!b)return;let url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='perspective-analysis.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});};
const scenes={};document.querySelectorAll('[data-example]').forEach((b,i)=>{const kind=b.dataset.example;scenes[kind]=example(kind);$('thumb'+i).style.backgroundImage=`url(${scenes[kind].toDataURL()})`;b.onclick=()=>{document.querySelectorAll('.example').forEach(x=>x.classList.toggle('selected',x===b));load(scenes[kind],b.querySelector('b').textContent+' · example');};});new ResizeObserver(draw).observe($('stage'));load(scenes.corridor,'The corridor · example');
